const auditLabels={ok:'Bilgi var',review:'İncele',missing:'Eksik',unknown:'Veri alınmadı'};
function auditHTML(p,detailed=false){
 const r=listingChecks(p),done=state.inspections?.[String(p.id)]?.fingerprint===r.fingerprint;
 const items=detailed?r.checks:r.checks.filter(c=>c.status!=='ok');
 return `<p class="small">${r.missing} eksik · ${r.review} inceleme · ${r.unknown} bilinmeyen${done?' · Son içerik kontrol edildi':''}</p><ul class="audit-list">${items.map(c=>`<li><span class="badge audit-${c.status}">${auditLabels[c.status]}</span> <strong>${esc(c.title)}</strong><p>${esc(c.detail)}</p></li>`).join('')||'<li>Temel bilgiler mevcut. Görsellerin ve açıklamanın uygunluğunu kendin kontrol et.</li>'}</ul>${r.unknown?'<p class="small">Eksik API verisi varken kontrol tamamlandı olarak işaretlenmez. Şimdi güncelleyi kullan.</p>':`<button data-inspect="${esc(p.id)}" ${done?'disabled':''}>${done?'Bu içerik kontrol edildi ✓':'İnceledim · bu içeriği işaretle'}</button>`}`;
}
function renderAudit(){
 const products=liveState?.snapshot?.products||[];const scope=document.querySelector('#audit-scope').value,filter=document.querySelector('#audit-status').value;
 const scoped=products.filter(p=>scope==='all'||p.age!==null&&p.age<30);
 const visible=scoped.filter(p=>filter==='all'||state.inspections?.[String(p.id)]?.fingerprint!==listingChecks(p).fingerprint);
 document.querySelector('#audit-summary').textContent=`${scoped.length} ürünün ${visible.length} tanesi gösteriliyor. İçerik değişince kontrol işareti geçersiz olur. Kaydedilen işaretler tarayıcıda tutulur; Etsy ilanını değiştirmez.`;
 document.querySelector('#audit-cards').innerHTML=visible.map(p=>`<article class="card"><h3>${esc(p.title)}</h3><p class="small">İlan #${esc(p.id)} · ${p.age??'bilinmiyor'} gün</p>${auditHTML(p)}<div class="card-actions"><button data-product="${esc(p.id)}">Detay ve tüm kontroller</button><a href="https://www.etsy.com/listing/${encodeURIComponent(p.id)}" target="_blank" rel="noopener noreferrer">Etsy’de incele ↗</a></div></article>`).join('')||'<p class="empty">Bu görünümde kontrol bekleyen ürün yok. Eski ürünleri görmek için Tüm aktif ürünler seç.</p>';
}
for(const id of ['audit-scope','audit-status'])document.querySelector('#'+id).onchange=renderAudit;
document.addEventListener('click',e=>{const b=e.target.closest('[data-inspect]');if(!b)return;const p=liveState?.snapshot?.products.find(p=>String(p.id)===b.dataset.inspect);if(!p)return;const r=listingChecks(p);if(r.unknown){message('Önce eksik API bilgisini güncelle.',true);return;}state.inspections??={};state.inspections[String(p.id)]={fingerprint:r.fingerprint,date:today()};if(save()){renderAudit();if(document.querySelector('#product-dialog').open)showProduct(p.id);message('İçerik incelemesi kaydedildi. Etsy ilanında değişiklik yapılmadı.');}});
