let ledgerEdit=null;
const dateUTC=n=>new Date(Date.now()+n*86400000).toISOString().slice(0,10);
document.querySelector('#finance-from').value=dateUTC(-29);document.querySelector('#finance-to').value=dateUTC(0);
function renderFinance(){
 const from=document.querySelector('#finance-from').value,to=document.querySelector('#finance-to').value;if(!from||!to)return;
 if(from>to){document.querySelector('#finance-scope').textContent='Başlangıç, bitişten sonra olamaz.';document.querySelector('#finance-cards').innerHTML='';return;}
 const snapshot=liveState?.snapshot,stamp=Date.parse(snapshot?.salesUpdated||snapshot?.updated);const known=Number.isFinite(stamp)&&Date.now()-stamp<=2*86400000;const within=known&&Date.parse(from+'T00:00:00Z')>=stamp-90*86400000&&Date.parse(to+'T00:00:00Z')<=stamp;
 const products=within?snapshot.products||[]:[];const r=financeSummary(products,state.ledger||[],from,to);
 document.querySelector('#finance-scope').textContent=within?`Dönem: ${from} – ${to} (UTC); son gün tamamlanmamışsa verisi son senkronizasyona kadardır. Yalnızca şu anda aktif ürünlerin bedelleri. ${r.unknown} üründe tutar verisi alınamadı; eksikler toplamda yok. Diğer satışlar, vergiler, döviz dönüşümü ve giderler bilinmeden net kâr hesaplanmaz.`:'Seçilen dönem güncel 90 günlük API kapsamı içinde değil veya satış verisi yok. Aşağıda yalnızca manuel kayıtlar hesaplanır; otomatik gelir eksiktir.';
 document.querySelector('#finance-cards').innerHTML=r.rows.map(t=>`<article class="card"><span class="badge">${esc(t.currency)}</span><h3>Kayıtlı bakiye: ${t.balance.toFixed(2)}</h3><p>API ürün bedeli: ${t.automatic.toFixed(2)}<br>Ek gelir: ${t.income.toFixed(2)}<br>Gider: ${t.expense.toFixed(2)}<br>İade: ${t.refund.toFixed(2)}</p><p class="small">Net kâr değildir; yalnızca kapsamdaki kayıtların farkı.</p></article>`).join('')||'<p class="empty">Bu dönemde tutar kaydı yok. Yeni sürümle satışları güncelle veya gider kaydı ekle.</p>';
 document.querySelector('#ledger-rows').innerHTML=(state.ledger||[]).filter(r=>r.date>=from&&r.date<=to).sort((a,b)=>b.date.localeCompare(a.date)).map(r=>`<tr><td>${esc(r.date)}</td><td>${{income:'Ek gelir',expense:'Gider',refund:'İade'}[r.kind]} / ${esc(r.category)}</td><td>${esc(r.note)}</td><td>${r.amount.toFixed(2)} ${esc(r.currency)}</td><td><button data-ledger-edit="${esc(r.id)}">Düzenle</button><button class="delete" data-ledger-delete="${esc(r.id)}">Sil</button></td></tr>`).join('')||'<tr><td colspan="5" class="empty">Bu dönemde manuel kayıt yok.</td></tr>';
}
for(const id of ['finance-from','finance-to'])document.querySelector('#'+id).onchange=renderFinance;
function resetLedger(){ledgerEdit=null;const f=document.querySelector('#ledger-form');f.reset();f.elements.date.value=today();document.querySelector('#ledger-submit').textContent='Kaydı ekle';document.querySelector('#ledger-cancel').hidden=true;}
document.querySelector('#ledger-form').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));try{d.amount=number(d.amount);if(d.amount<=0)throw Error('Tutar sıfırdan büyük olmalı.');d.id=ledgerEdit||uid();state.ledger??=[];if(ledgerEdit)state.ledger=state.ledger.map(r=>r.id===ledgerEdit?d:r);else state.ledger.push(d);if(save()){resetLedger();renderFinance();message('Defter kaydı kaydedildi. Etsy hesabında işlem yapılmadı.');}}catch(err){message(err.message,true);}};
document.querySelector('#ledger-cancel').onclick=resetLedger;
document.addEventListener('click',e=>{const b=e.target.closest('button');const id=b?.dataset.ledgerEdit||b?.dataset.ledgerDelete;if(!id)return;const r=state.ledger?.find(r=>r.id===id);if(!r)return;if(b.dataset.ledgerDelete){if(!confirm('Bu defter kaydı silinsin mi?'))return;state.ledger=state.ledger.filter(x=>x.id!==id);if(save())renderFinance();}else{ledgerEdit=id;const f=document.querySelector('#ledger-form');for(const k of ['kind','category','date','amount','currency','note'])f.elements[k].value=r[k];document.querySelector('#ledger-submit').textContent='Kaydı güncelle';document.querySelector('#ledger-cancel').hidden=false;f.scrollIntoView({behavior:'smooth'});}});
async function checkUpdate(){const el=document.querySelector('#update-result');document.querySelector('#check-update').disabled=true;try{const r=await fetch('/api/version');const j=await r.json();if(!r.ok)throw Error(j.error||'Sürüm kontrolü başarısız');document.querySelector('#app-version').textContent='Sürüm '+j.current;el.textContent=j.available?'Yeni sürüm '+j.latest+' var. Önce Yedek indir; eski pencereyi kapat, ZIP’i ayrı klasöre çıkartıp başlat. Bağlantı dosyası korunur.':'Daha yeni sürüm yok. Depo sürümü: '+j.latest+'.';document.querySelector('#update-download').hidden=!j.available;}catch(e){el.textContent='Kontrol edilemedi: '+e.message+' · Paneli kullanmaya devam edebilirsin.';}finally{document.querySelector('#check-update').disabled=false;}}
document.querySelector('#check-update').onclick=checkUpdate;
fetch('version.json').then(r=>r.json()).then(j=>document.querySelector('#app-version').textContent='Sürüm '+j.version).catch(()=>document.querySelector('#app-version').textContent='Sürüm bilgisi alınamadı');
if(!localAPI){document.querySelector('#check-update').hidden=true;document.querySelector('#update-result').textContent='Yeni sürüm kontrolü Windows yerel panelinde kullanılabilir.';}
resetLedger();renderFinance();

let marketData=null;
async function refreshMarket(){if(!localAPI){document.querySelector('#market-status').textContent='Canlı takip Windows yerel panelinde kullanılabilir.';document.querySelector('#market-form').hidden=true;document.querySelector('#market-sync').disabled=true;document.querySelector('#market-export').disabled=true;return;}try{marketData=await etsyRequest('market');marketProblem='';document.querySelector('#market-status').textContent=(marketData.busy?'Takipler güncelleniyor…':'Takip kayıtları: '+marketData.watches.length)+' · Aynı kayıt için başarılı gözlemler 6 saat aralıklı; hata sonrası bekleme uygulanır.';document.querySelector('#market-sync').disabled=marketData.busy;
 setMarkup('#market-cards',marketData.watches.map(w=>{const c=w.current,d=w.comparison;const summary=marketPriceSummary(c?.listings||[]);const prices=summary.medians.map(m=>esc(m.currency)+': '+m.median.toFixed(2)+' ('+m.count+' dijital ilan)').join('<br>');return `<article class="card"><span class="badge">${w.kind==='shop'?'Mağaza':'Arama ifadesi'}</span><h3>${esc(w.query)}</h3>${w.error?`<p class="error">${esc(w.error)}</p><p class="small">Eski başarılı gözlem korunur. ${w.retryAfter?'Yeniden deneme: '+esc(new Date(w.retryAfter).toLocaleString('tr-TR',{timeZone:'Europe/Istanbul'})):''}</p>`:''}${c?`<p class="small">Son gözlem: ${esc(new Date(c.updated).toLocaleString('tr-TR',{timeZone:'Europe/Istanbul'}))}</p><p>API sonuç sayısı: <strong>${c.reportedCount??'Bilinmiyor'}</strong><br>Veri çekildi: ${c.sampled} ilan · Dijital türünde: ${summary.digital} · Türü bilinmeyen: ${summary.unknownType}</p><p>Örneklem medyan fiyatı:<br>${prices||esc(summary.reason)}</p>${d.baseline?'<p class="candidate-insight">İlk kayıt. Sonraki başarılı gözlemde farklar hesaplanacak.</p>':`<p class="candidate-insight">${d.newObserved.length} yeni gözlenen · ${d.priceChanges.length} fiyat değişimi · ${d.missingObserved.length} örneklem dışına çıkan</p><details><summary>Fiyat değişimleri</summary>${d.priceChanges.map(x=>`<p>${esc(x.title)}: ${x.before.toFixed(2)} → ${x.after.toFixed(2)} ${esc(x.currency)}</p>`).join('')||'<p>Ortak ilanlarda fiyat değişimi yok.</p>'}</details>`}<details><summary>Gözlenen ilanlar</summary>${c.listings.slice(0,20).map(l=>`<p><a href="https://www.etsy.com/listing/${encodeURIComponent(l.id)}" target="_blank" rel="noopener noreferrer">${esc(l.title)}</a> · ${esc(l.type||'Tür bilinmiyor')}</p>`).join('')}<p class="small">Ekranda ilk 20 ilan; tam örneklem takip yedeğinde.</p></details><details><summary>Gözlem geçmişi (${w.history.length})</summary>${w.history.map(h=>`<p class="small">${esc(new Date(h.updated).toLocaleString('tr-TR',{timeZone:'Europe/Istanbul'}))} · API ${h.reportedCount??'—'} / örneklem ${h.sampled}</p>`).join('')}</details>`:'<p class="empty">İlk gözlem bekleniyor.</p>'}<button class="delete" data-market-delete="${esc(w.id)}">Takibi sil</button></article>`;}).join('')||'<p class="empty">Önce 2–3 İngilizce STL araması ekle. Araştırmada gördüğün mağazaları daha sonra takip edebilirsin.</p>');}catch(e){marketProblem=e.message;document.querySelector('#market-status').textContent=e.message;}refreshOverview();}
document.querySelector('#market-form').onsubmit=async e=>{e.preventDefault();try{await etsyRequest('market',{action:'add',...Object.fromEntries(new FormData(e.target))});e.target.reset();await refreshMarket();message('Takip eklendi. İlk gözlem başlatıldı.');}catch(err){message(err.message,true);}};
document.querySelector('#market-sync').onclick=async()=>{try{await etsyRequest('market',{action:'sync'});await refreshMarket();}catch(e){message(e.message,true);}};
document.addEventListener('click',async e=>{const b=e.target.closest('[data-market-delete]');if(!b||!confirm('Takip ve gözlem geçmişi silinsin mi?'))return;try{await etsyRequest('market',{action:'remove',id:b.dataset.marketDelete});await refreshMarket();}catch(err){message(err.message,true);}});
document.querySelector('#market-export').onclick=async()=>{if(!marketData)return;let exported;try{exported=await etsyRequest('market-export');}catch(e){message(e.message,true);return;}const blob=new Blob([JSON.stringify(exported,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='stl-pazar-gozlemleri-'+today()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
void refreshMarket();if(localAPI)setInterval(refreshMarket,15000);

function validShareDate(value){const stamp=Date.parse(value+'T00:00:00Z');return /^\d{4}-\d{2}-\d{2}$/.test(value)&&Number.isFinite(stamp)&&new Date(stamp).toISOString().slice(0,10)===value;}
function validShareURL(value){try{const u=new URL(value);return u.protocol==='https:'&&!u.username&&!u.password;}catch{return false;}}
let shareEdit=null;
function resetShare(){shareEdit=null;const f=document.querySelector('#share-form');f.reset();f.elements.date.value=today();document.querySelector('#share-submit').textContent='Kaydı ekle';document.querySelector('#share-cancel').hidden=true;}
function renderSharing(){
 const products=liveState?.snapshot?.products||[],form=document.querySelector('#share-form'),select=form.elements.product,old=select.value;
 const known=new Map(products.map(p=>[String(p.id),p.title]));for(const r of state.shares||[])if(!known.has(r.product))known.set(r.product,r.title+' (aktif listede yok)');
 select.innerHTML=[...known].map(([id,title])=>`<option value="${esc(id)}">${esc(title)}</option>`).join('');if(known.has(old))select.value=old;document.querySelector('#share-submit').disabled=!known.size;
 const filter=document.querySelector('#share-filter').value;
 const cards=[...(state.shares||[])].filter(r=>filter==='all'||r.status===filter).sort((a,b)=>b.date.localeCompare(a.date));
 document.querySelector('#share-cards').innerHTML=cards.map(r=>{const p=products.find(p=>String(p.id)===r.product);const analysis=sharingComparison(p,r,liveState?.snapshot?.salesUpdated||liveState?.snapshot?.updated);const overlap=r.status==='shared'&&(state.shares||[]).some(x=>x.id!==r.id&&x.product===r.product&&x.status==='shared'&&Math.abs(Date.parse(x.date)-Date.parse(r.date))<14*86400000);return `<article class="card"><span class="badge">${esc(r.channel)} · ${r.status==='shared'?'Paylaşıldı':'Planlandı'}</span><h3>${esc(p?.title||r.title)}</h3><p>${esc(r.date)} · ${esc(r.note)}</p>${r.url?`<a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">Paylaşımı aç ↗</a>`:''}<p>${r.metric===null?'Trafik ölçümü bilinmiyor':`${r.metric} ${r.metricType==='clicks'?'dış bağlantı tıklaması':'kaynak ziyareti'} · ${esc(r.source)} · ${esc(r.measured)} tarihine kadar (manuel)`}</p><span class="badge">${esc(analysis.label)}</span>${analysis.before!==undefined?`<p>Önceki 7 gün: ${analysis.before} adet · Sonraki 7 gün: ${analysis.after} adet</p>`:''}<p class="small">${esc(analysis.reason)}${overlap?' Aynı üründe yakın tarihli başka paylaşım var; dönemler çakışıyor.':''}</p><div class="card-actions"><button data-share-edit="${esc(r.id)}">Düzenle / sonucu ekle</button>${p?`<button data-product="${esc(p.id)}">Ürünü incele</button>`:''}<button class="delete" data-share-delete="${esc(r.id)}">Sil</button></div></article>`;}).join('')||'<p class="empty">Paylaşımı planlayıp burada kaydet. Sonuçları daha sonra gerçek ölçümlerle değerlendir.</p>';
 const due=(state.shares||[]).filter(r=>r.status==='planned'&&r.date<=today());document.querySelector('#share-tasks').innerHTML=due.slice(0,3).map(r=>`<article class="card"><span class="badge">Paylaşım planı · ${esc(r.channel)}</span><h3>${esc(r.title)}</h3><p>${esc(r.date)} · Planladığın paylaşımı yapıp kaydı Paylaşıldı olarak güncelle.</p><button data-share-edit="${esc(r.id)}">Planı aç</button></article>`).join('');
}
document.querySelector('#share-filter').onchange=renderSharing;
document.querySelector('#share-form').onsubmit=e=>{e.preventDefault();try{const d=Object.fromEntries(new FormData(e.target));for(const k of ['url','note','source'])d[k]=d[k].trim();if(!validShareDate(d.date))throw Error('Geçerli tarih gir.');if(d.url&&!validShareURL(d.url))throw Error('HTTPS paylaşım bağlantısı gir.');if(d.status==='shared'&&d.date>today())throw Error('Paylaşıldı tarihi gelecekte olamaz.');d.metric=number(d.metric,true);if(d.metric!==null){if(!Number.isInteger(d.metric))throw Error('Ölçümü tam sayı gir.');if(d.status!=='shared'||!d.source||!validShareDate(d.measured)||d.measured<d.date||d.measured>today())throw Error('Ölçüm için Paylaşıldı seç, kaynağı ve paylaşım sonrası ölçüm tarihini gir.');}else{d.source='';d.measured='';}const p=liveState?.snapshot?.products.find(p=>String(p.id)===d.product);d.title=p?.title||(state.shares||[]).find(r=>r.product===d.product)?.title;if(!d.title)throw Error('Önce ürünleri güncelle.');d.id=shareEdit||uid();state.shares??=[];if(shareEdit)state.shares=state.shares.map(r=>r.id===shareEdit?d:r);else state.shares.push(d);if(save()){resetShare();renderSharing();message('Paylaşım kaydı kaydedildi. Platforma gönderim yapılmadı.');}}catch(err){message(err.message,true);}};
document.querySelector('#share-cancel').onclick=resetShare;
document.addEventListener('click',e=>{const b=e.target.closest('button'),id=b?.dataset.shareEdit||b?.dataset.shareDelete;if(!id)return;const r=state.shares?.find(r=>r.id===id);if(!r)return;if(b.dataset.shareDelete){if(!confirm('Paylaşım kaydı silinsin mi?'))return;state.shares=state.shares.filter(x=>x.id!==id);if(save()){if(shareEdit===id)resetShare();renderSharing();}}else{shareEdit=id;renderSharing();const f=document.querySelector('#share-form');for(const k of ['product','channel','status','date','url','note','metricType','metric','source','measured'])f.elements[k].value=r[k]??'';document.querySelector('#share-submit').textContent='Kaydı güncelle';document.querySelector('#share-cancel').hidden=false;f.scrollIntoView({behavior:'smooth',block:'center'});f.elements.status.focus();}});
resetShare();renderSharing();

function setMarkup(selector,html){
 const element=document.querySelector(selector);if(markupCache.get(element)===html)return;
 const expanded=[...element.querySelectorAll('details')].map(d=>d.open),scroll=[...element.querySelectorAll('.table-wrap')].map(d=>d.scrollTop);
 element.innerHTML=html;markupCache.set(element,html);
 element.querySelectorAll('details').forEach((d,i)=>{if(expanded[i])d.open=true;});
 element.querySelectorAll('.table-wrap').forEach((d,i)=>{if(scroll[i])d.scrollTop=scroll[i];});
}
function displayDay(value){return value.split('-').reverse().join('.');}
function salesChartHTML(result){
 if(!result.ready)return `<p class="empty">${esc(result.reason)}</p>`;
 const width=420,height=146,top=10,bottom=113,max=Math.max(1,...result.series.map(r=>r.quantity)),step=(width-30)/result.series.length;
 const bars=result.series.map((r,i)=>{const x=20+i*step,h=r.quantity/max*(bottom-top);return `<g><title>${esc(r.date)}: ${r.quantity} adet</title><rect x="${x}" y="${top}" width="${step-3}" height="${bottom-top}" fill="transparent"/><rect class="chart-bar" x="${x}" y="${bottom-h}" width="${step-6}" height="${h}" rx="3"/></g>`;}).join('');
 return `<strong class="chart-total">${result.total}<small>adet / 14 tam gün</small></strong><svg viewBox="0 0 ${width} ${height}" role="img" aria-label="Son 14 tam gündeki toplam ${result.total} adet satış. Günlük sayılar aşağıdaki tabloda."><line class="chart-grid" x1="18" y1="${top}" x2="${width}" y2="${top}"/><line class="chart-grid" x1="18" y1="${bottom}" x2="${width}" y2="${bottom}"/><text class="chart-label" x="0" y="${top+4}">${max}</text>${bars}<text class="chart-label" x="20" y="139">${displayDay(result.series[0].date).slice(0,5)}</text><text class="chart-label" x="${width-40}" y="139">${displayDay(result.series.at(-1).date).slice(0,5)}</text></svg><p class="chart-caption">${result.known} aktif ürün · Tam UTC günleri${result.unknown?' · '+result.unknown+' ürünün eksik verisi dışarıda':''}</p><details class="chart-values"><summary>Günlük adetler</summary><div class="table-wrap"><table><thead><tr><th>Tarih (UTC)</th><th>Adet</th></tr></thead><tbody>${result.series.map(r=>`<tr><td>${r.date}</td><td>${r.quantity}</td></tr>`).join('')}</tbody></table></div></details>`;
}
function renderSalesCharts(){const snapshot=liveState?.snapshot,result=dailySalesSeries(snapshot?.products||[],snapshot?.salesUpdated||snapshot?.updated);const html=salesChartHTML(result);setMarkup('#home-chart',html);setMarkup('#weekly-chart',html);}
function renderMarketSuggestions(){
 const products=liveState?.snapshot?.products||[],watches=marketData?.watches||[];
 const suggestions=suggestedMarketQueries(products).filter(query=>!watches.some(w=>w.kind==='keyword'&&w.query.toLowerCase()===query.toLowerCase()));
 document.querySelector('#market-suggestions').innerHTML=!products.length?'<p>Ürünler geldiğinde mağazana uygun hazır aramalar burada görünecek.</p>':!suggestions.length?'<p>Ürün gruplarına uygun hazır aramalar takip listende veya henüz tanınan bir ürün grubu yok.</p>':`<h3>Mağazandan yola çıkan aramalar</h3><p>Başlık ve etiketlerine göre önerildi. Birine dokun; ilan gözlemlerini otomatik toplamaya başlayalım.</p><div class="tools">${suggestions.map(query=>`<button data-watch-query="${esc(query)}" ${!localAPI||!liveState?.configured||watches.length>=10||pendingWatchQueries.has(query)?'disabled':''}>${esc(query)} ＋</button>`).join('')}</div><p class="settings-note">Bunlar talep ölçümü veya düşük rekabet önerisi değildir.</p>`;
}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-watch-query]');if(!b||b.disabled)return;const query=b.dataset.watchQuery;if(pendingWatchQueries.has(query))return;pendingWatchQueries.add(query);renderMarketSuggestions();try{await etsyRequest('market',{action:'add',kind:'keyword',query});await refreshMarket();message('Takip eklendi. İlk Etsy gözlemi hazırlanıyor.');}catch(error){message(error.message,true);}finally{pendingWatchQueries.delete(query);renderMarketSuggestions();}});
function observationHTML(row){const names={title:'Başlık',description:'Açıklama',tags:'Etiketler',images:'Görseller',type:'İlan türü',price:'Fiyat'},value=v=>typeof v==='string'?v:JSON.stringify(v,null,2);const changes=Object.entries(row.content||{}).map(([field,c])=>`<details><summary>${esc(names[field]||field)} · önce/sonra</summary><div class="diff-grid"><div><strong>Önce</strong><pre>${esc(value(c.before))}</pre></div><div><strong>Sonra</strong><pre>${esc(value(c.after))}</pre></div></div></details>`).join('');return `<article class="change-entry"><span class="badge">Otomatik gözlem</span><h3>${esc(row.title)}</h3><p>${esc(row.fields.map(f=>names[f]||f).join(', '))} değişikliği · ${esc(new Date(row.observedAt).toLocaleString('tr-TR',{timeZone:'Europe/Istanbul'}))}</p><p class="small">Önceki kayıt: ${esc(new Date(row.previousObservedAt).toLocaleString('tr-TR',{timeZone:'Europe/Istanbul'}))}. Tam düzenleme zamanı bilinmiyor.</p>${changes||'<p class="small">Bu eski gözlemde önce/sonra içerikleri saklanmamış; doldurulmadı.</p>'}</article>`;}
function renderProductObservations(product){const rows=(workspaceData?.history?.observations||liveState?.snapshot?.observations||[]).filter(r=>String(r.product)===String(product.id));document.querySelector('#product-observations').innerHTML=rows.length?`<details class="optional-tools"><summary>Otomatik gözlenen değişiklikler (${rows.length})</summary>${rows.slice(-8).reverse().map(observationHTML).join('')}</details>`:'';}
function refreshOverview(){if(dashboardReady)renderOverview();}
function renderOverview(){
 const snapshot=liveState?.snapshot,brief=dailyBrief(snapshot?{...snapshot,products:snapshot.products.map(p=>({...p,decision:decisionFor(p)}))}:null,state),s=liveState;
 document.querySelector('#home-date').textContent=new Intl.DateTimeFormat('tr-TR',{timeZone:'Europe/Istanbul',dateStyle:'full'}).format(new Date());
 document.querySelector('#home-connection').textContent=!localAPI?'Statik araştırma paneli':connectionProblem?'Yerel sunucuya ulaşılamadı':!s?'Bağlantı kontrol ediliyor…':s.connected?'Etsy bağlı · '+(s.shop||'Mağaza yükleniyor'):s.configured?'Etsy yetkilendirmesi gerekiyor':'Etsy bağlantısını tamamla';
 const detail=[];
 if(!localAPI)detail.push('Canlı mağaza ve rakip verileri Windows yerel panelinde kullanılabilir.');
 else if(connectionProblem)detail.push('Yerel sunucunun açık olduğunu kontrol et. Son alınan kayıtlar korunuyor.');
 else if(s?.busy||syncingEtsy)detail.push('Etsy verileri güncelleniyor…');
 if(s?.error)detail.push('Son güncelleme tamamlanamadı. Ayrıntılar Ayarlar’da.');
 if(snapshot){const stamp=snapshot.salesUpdated||snapshot.updated;detail.push('Son ürün/satış kaydı: '+new Date(stamp).toLocaleString('tr-TR',{timeZone:'Europe/Istanbul'}));const unknown=(snapshot.products||[]).filter(p=>p.salesAvailable===false).length;if(unknown)detail.push(unknown+' üründe satış bilgisi bekleniyor.');if(!brief.fresh)detail.push('Veri eski; güncelle.');}
 else if(localAPI&&s)detail.push('Henüz başarılı ürün kaydı yok.');
 document.querySelector('#home-data-status').textContent=detail.join(' · ');
 document.querySelector('.home-toolbar').classList.toggle('warning',!!connectionProblem||!!s?.error||!!snapshot&&!brief.fresh);
 document.querySelector('#home-sync').disabled=!localAPI||!s?.connected||s.busy||syncingEtsy;document.querySelector('#toolbar-sync').disabled=document.querySelector('#home-sync').disabled;document.querySelector('#toolbar-sync').textContent=s?.busy||syncingEtsy?'Yenileniyor…':'Yenile ↻';
 const known30=(snapshot?.products||[]).filter(p=>p.salesAvailable!==false&&p.periods?.some(r=>r.days===30));const quantity30=brief.fresh&&known30.length?known30.reduce((sum,p)=>sum+p.periods.find(r=>r.days===30).quantity,0):null;
 setMarkup('#home-metrics',[['Aktif ürün',brief.active,'Etsy’den otomatik'],['Son 30 gün satış',quantity30,known30.length+' aktif ürünün verisinden'],['İnceleme önerisi',snapshot?brief.review:null,'Satış veya ilan bilgisi uyarısı'],['Yeni ürün',snapshot?(snapshot.products||[]).filter(p=>p.age!==null&&p.age<30).length:null,'İlk 30 günündeki ilanlar']].map(([label,value,note])=>`<div class="stat"><span>${label}</span><strong>${value??'—'}</strong><small>${esc(note)}</small></div>`).join(''));
 for(const kind of ['support','sharing']){const option=document.querySelector('#home-filter option[value='+kind+']');option.hidden=!brief.tasks.some(t=>t.kind===kind);}
 const homeFilter=document.querySelector('#home-filter');if(homeFilter.selectedOptions[0]?.hidden)homeFilter.value='all';
 const filter=homeFilter.value,tasks=brief.tasks.filter(t=>filter==='all'||t.kind===filter),shown=tasks.slice(0,homeLimit);
 document.querySelector('#home-task-summary').textContent=tasks.length?`${tasks.length} öneriden ${shown.length} tanesi burada.`:!brief.fresh?'Güncel veriler geldikçe öneriler burada görünecek.':'Bu görünümde öne çıkan bir uyarı yok.';
 setMarkup('#home-task-cards',shown.map(t=>`<article class="card"><span class="badge">${esc(t.label)}</span><h3>${esc(t.title)}</h3><p>${esc(t.reason)}</p><div class="card-actions">${t.kind==='sharing'||t.target==='sharing'?`<button data-share-edit="${esc(t.id)}" class="primary">Kaydı aç →</button>`:t.kind==='support'?`<a href="#support" class="button">Müşteri işlerine git →</a><button data-support-toggle="${esc(t.id)}">Çözüldü ✓</button>`:`<a href="#${esc(t.target)}" class="button">Bölümü aç →</a>`}${t.product&&t.kind!=='support'?`<button data-product="${esc(t.product)}">Ürünü incele</button>`:''}${t.review?`<button data-review="${esc(t.product)}">İnceledim ✓</button><button data-snooze="${esc(t.product)}" data-days="3">3 gün sonra</button>`:''}</div></article>`).join('')||`<div class="empty">${!snapshot&&filter==='all'?'Canlı veriler geldikçe ürün işleri burada görünecek. Kaydettiğin müşteri işleri ve paylaşım planlarını bağlantı olmadan da takip edebilirsin.':'Şu an zorunlu bir ürün işi yok. Yeni dosya seçeceksen önce dosyayı kontrol et, ardından pazar örneklerini incele.'}<div class="card-actions"><a class="button" href="#files">STL dosyasına bak →</a><a class="button" href="#market">Pazarda ele →</a></div></div>`);
 document.querySelector('#home-more').hidden=shown.length>=tasks.length;renderSalesCharts();renderMarketSuggestions();renderWorkbench();
 const weekly=weeklySummary(snapshot?.products||[],snapshot?.salesUpdated||snapshot?.updated),rows=weekly.rows.filter(r=>r.ready);
 document.querySelector('#home-weekly').textContent=!weekly.ready?weekly.reason:!rows.length?'İki haftalık karşılaştırmaya uygun aktif ürün yok.':`${rows.length} karşılaştırılabilir aktif üründe önceki hafta ${weekly.previous}, son hafta ${weekly.current} adet. Son dönem: ${displayDay(weekly.from)} – ${displayDay(weekly.to)}.`;
 const watches=marketData?.watches||[];
 document.querySelector('#home-market').textContent=!localAPI?'Canlı rakip takibi Windows yerel panelinde kullanılabilir.':marketProblem?'Takip bilgisi alınamadı: '+marketProblem:!marketData?'Takip bilgisi kontrol ediliyor…':!watches.length?'Henüz takip yok. Bir rakip mağaza veya İngilizce arama ifadesi ekle.':`${watches.length} takipten ${watches.filter(w=>w.current).length} tanesinde gözlem var. ${watches.filter(w=>w.error).length} takipte hata var.${marketData.busy?' Yeni gözlemler alınıyor…':''}`;
}
