function activateWorkspace(focus=false){
 const panels=[...document.querySelectorAll('main > section')];
 let requested;try{requested=decodeURIComponent(location.hash.slice(1));}catch{requested='overview';}
 const active=panels.find(p=>p.id===requested)||document.querySelector('#overview');
 for(const panel of panels)panel.hidden=panel!==active;renderWorkbench();
 document.querySelectorAll('aside nav a').forEach(a=>{const parentRoute=['listing-audit','daily','change-evaluations','history','files'].includes(active.id)?'shop':active.id==='finance'?'weekly':!['overview','shop','weekly','opportunities','market','live','deliveries','preparation'].includes(active.id)?'live':active.id;const selected=a.getAttribute('href')==='#'+parentRoute;if(selected){a.setAttribute('aria-current','page');const group=a.closest('details');if(group)group.open=true;}else a.removeAttribute('aria-current');});
 const heading=active.querySelector('h2');
 const names={deliveries:'Teslim ve hazırlık',preparation:'İlan taslakları',files:'Dosya kontrolü',history:'Hafıza',messages:'Müşteri yanıtları','change-evaluations':'Sonuç takibi',overview:'Bugün',shop:'Ürünler',weekly:'Satışlar',opportunities:'Ürün grupları',market:'Pazar gözlemi',live:'Ayarlar'};document.querySelector('#workspace-title').textContent=names[active.id]||heading?.textContent||'Çalışma alanı';document.querySelector('#workspace-subtitle').textContent=active.id==='overview'?'Mağazana bir bakış. Sonraki adımın burada.':'Verilerin hazır. Ayrıntılara gerektiği kadar bak.';
 if(heading)heading.tabIndex=-1;
 if(focus){document.querySelector('aside').classList.remove('is-open');document.querySelector('#menu-toggle').setAttribute('aria-expanded','false');heading?.focus({preventScroll:true});active.scrollIntoView({block:'start'});}
}
function openWorkspace(id){if(location.hash!=='#'+id)history.pushState(null,'','#'+id);activateWorkspace();}
// Reveal the sharing form before existing edit handlers populate and focus it.
document.addEventListener('click',e=>{if(e.target.closest('[data-share-edit]'))openWorkspace('sharing');},true);
document.querySelector('aside nav').addEventListener('click',e=>{const a=e.target.closest('a[href^="#"]');if(!a)return;e.preventDefault();openWorkspace(a.getAttribute('href').slice(1));activateWorkspace(true);});
window.addEventListener('hashchange',()=>activateWorkspace(true));
window.addEventListener('popstate',()=>activateWorkspace(true));
document.querySelector('#menu-toggle').onclick=()=>{const open=document.querySelector('aside').classList.toggle('is-open');document.querySelector('#menu-toggle').setAttribute('aria-expanded',String(open));};
