window.STLAtelierUI.init({getState:()=>state,getWorkspace:()=>workspaceData,getLive:()=>liveState,isLocal:localAPI,save,message,esc,setMarkup,openWorkspace,etsyRequest,refreshEtsy,refreshOverview,
 async flush(){await writeQueue;if(saveBlocked)throw Error('Kayıt saklanamadı; sekme kopyanı yedekle.');},
 async claimLegacy(id,shopId){await writeQueue;if(saveBlocked)throw Error('Önce kayıt hatasını çöz.');workspaceData=await workspaceRequest('/claim-legacy',{id,shopId,revision:stateRevision});stateRevision=workspaceData.revision;state=workspaceData.state||initial();clearUndo();resetScopeInputs();render();renderShop();}
});
